/* ===== helpers for the 2021 and 2023 papers ===== */
/* DF: displayed formula along a horizontal backbone. item=[sym, up, down, bondOrderToNext]; up/down: null|"H"|"=O"|"CH3"|["O","H"] */
function DF(chain,eL,eR,label,cap){
  const hasM=chain.some(c=>c[1]==="CH3"||c[2]==="CH3"),dx=hasM?74:58,lv=v=>!v?0:v==="CH3"?2:Array.isArray(v)?v.length:1;
  const lu=Math.max(0,...chain.map(c=>lv(c[1]))),ld=Math.max(0,...chain.map(c=>lv(c[2])));
  const x0=eL?50:28,y0=26+lu*38,A=[],B=[],X=i=>x0+i*dx;
  chain.forEach((c,i)=>{
    A.push(["c"+i,X(i),y0,c[0]]);if(i)B.push(["c"+(i-1),"c"+i,chain[i-1][3]||1]);
    [[c[1],-1,"u"],[c[2],1,"d"]].forEach(([v,s,t])=>{
      if(!v)return;const id="c"+i+t;
      if(v==="H"){A.push([id,X(i),y0+s*38,"H"]);B.push(["c"+i,id]);}
      else if(v==="=O"){A.push([id,X(i),y0+s*38,"O"]);B.push(["c"+i,id,2]);}
      else if(v==="CH3"){A.push([id,X(i),y0+s*38,"C"]);B.push(["c"+i,id]);
        A.push([id+"a",X(i),y0+s*76,"H"]);B.push([id,id+"a"]);
        A.push([id+"b",X(i)-32,y0+s*38,"H"]);B.push([id,id+"b"]);
        A.push([id+"c",X(i)+32,y0+s*38,"H"]);B.push([id,id+"c"]);}
      else{let prev="c"+i;v.forEach((e,k)=>{const nid=id+k;A.push([nid,X(i),y0+s*38*(k+1),e]);B.push([prev,nid]);prev=nid})}
    });
  });
  const n=chain.length-1;
  if(eL){A.push(["eL",x0-38,y0,eL==="-"?"":eL]);B.push(["c0","eL"])}
  if(eR){A.push(["eR",X(n)+38,y0,eR==="-"?"":eR]);B.push(["c"+n,"eR"])}
  const w=X(n)+(eR?38:0)+34,h=y0+ld*38+30;
  return DISP(A,B,Math.round(w),Math.round(h),label).replace('<figure class="fig"',`<figure class="fig"`)+(cap?"":"");
}
const FBLANK=(k,cap)=>`<figure class="fig" style="max-width:340px"><div class="svgw">${covSVG(COVM[k][2],"Outline of the "+COVM[k][0].replace(/~/g,"")+" molecule",true)}</div><figcaption>${cap}</figcaption></figure>`;
function FIG23(ans){
  const ring=(cx,cy,r,sym,ch,col)=>{let s=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="currentColor" stroke-opacity=".6" stroke-width="1.4"/>`;
    [80,100,170,190,260,280,350,10].slice(0,ch).forEach(a=>{const t=a*Math.PI/180,x=cx+r*Math.cos(t),y=cy-r*Math.sin(t);
      s+=col==="d"?`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3.2" style="fill:var(--bad)"/>`:`<path d="M${(x-3).toFixed(1)} ${(y-3).toFixed(1)}l6 6m0 -6l-6 6" style="stroke:var(--accent)" stroke-width="2" stroke-linecap="round" fill="none"/>`});
    return s};
  const br=(cx,ch)=>`<path d="M${cx-52} 18H${cx-60}V122H${cx-52}M${cx+52} 18H${cx+60}V122H${cx+52}" fill="none" stroke="currentColor" stroke-width="1.6"/><text x="${cx+66}" y="22" font-size="14" font-weight="600" fill="currentColor">${ch}</text>`;
  const K=cx=>ring(cx,70,22,"K",0)+ring(cx,70,42,"K",8,"d")+`<text x="${cx}" y="75" text-anchor="middle" font-size="14" font-weight="700" fill="currentColor">K</text>`+br(cx,ans?"+":"....");
  const O=cx=>ring(cx,70,22,"O",2,"x")+(ans?ring(cx,70,42,"O",8,"x"):"")+`<text x="${cx}" y="75" text-anchor="middle" font-size="14" font-weight="700" fill="currentColor">O</text>`+br(cx,ans?"2−":"....");
  return `<figure class="fig" style="max-width:560px"><svg viewBox="0 0 520 140" role="img" aria-label="Fig. 2.1: electronic configurations of the ions in potassium oxide, ${ans?"completed":"to complete"}">${K(80)}${O(260)}${K(440)}</svg><figcaption>Fig. 2.1${ans?" (model answer)":""}</figcaption></figure>`;
}
